def relay_balance_window(adjustments, target):
    earliest = {0: -1}
    total = 0
    best = 0
    for index, value in enumerate(adjustments):
        total += value
        previous = earliest.get(total - target)
        if previous is not None:
            best = max(best, index - previous)
        if total not in earliest:
            earliest[total] = index
    return best

